import{_ as a,o as t,c as s,a0 as n}from"./chunks/framework.l1I-fhud.js";const u=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),i={name:"explanation/decisions.md"};function o(r,e,c,d,l,p){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the calls that shaped tamias, the alternatives rejected, and the consequences we live with.</p><h2 id="ports-and-adapters-flat-crates" tabindex="-1">Ports-and-adapters, flat crates <a class="header-anchor" href="#ports-and-adapters-flat-crates" aria-label="Permalink to &quot;Ports-and-adapters, flat crates&quot;">​</a></h2><p><strong>Decision:</strong> the engine is pure domain (<code>tamias-core</code>, no I/O); every external capability — source, store, cache, registry, deploy — is a trait with <code>-local</code>/<code>-cf</code>/platform impls in sibling crates.</p><p><strong>Alternatives:</strong> a monolithic binary; an async runtime with plugin traits loaded in-process.</p><p><strong>Consequence:</strong> impls are swappable and testable in isolation, and the binary stays sync and dependency-light. The cost is crate sprawl — the crate map is wide — and every new capability is a new port + impl pair rather than a function.</p><h2 id="content-types-are-declared-drivers-are-subprocesses" tabindex="-1">Content types are declared, drivers are subprocesses <a class="header-anchor" href="#content-types-are-declared-drivers-are-subprocesses" aria-label="Permalink to &quot;Content types are declared, drivers are subprocesses&quot;">​</a></h2><p><strong>Decision:</strong> a package&#39;s <code>type:</code> is manifest <em>data</em>; the manager launches <code>tamias-driver-&lt;type&gt;</code> as a subprocess over argv — &quot;no plugin system: files&quot;.</p><p><strong>Alternatives:</strong> linking product crates into the engine; an in-process plugin ABI (dlopen, WASM); a central registry of trusted drivers only.</p><p><strong>Consequence:</strong> adding a content type never changes the engine, and a malformed driver can&#39;t corrupt tamias&#39;s memory — but driver bugs are process boundaries, dispatch has a 120s timeout, and payload-shipped drivers needed the <code>--allow-drivers</code> consent gate. See <a href="/tamias/how-to/write-a-driver.html">Write a driver</a>.</p><h2 id="tamias-itself-stays-a-native-binary" tabindex="-1"><code>tamias</code> itself stays a native binary <a class="header-anchor" href="#tamias-itself-stays-a-native-binary" aria-label="Permalink to &quot;`tamias` itself stays a native binary&quot;">​</a></h2><p><strong>Decision:</strong> the <code>tamias</code> bin is never a <code>bins[]</code> shim — every shim in the org execs <code>tamias bin exec</code>, so tamias can&#39;t retire into a shim (bootstrap, T-007).</p><p><strong>Alternatives:</strong> shipping tamias as a pack like every other product CLI.</p><p><strong>Consequence:</strong> <code>cargo install tamias</code> works forever and shims never chase a moving helper; the cost is tamias alone among product CLIs is cargo-installable, which the docs must keep explaining.</p><h2 id="yaml-is-the-standard-config-toml-the-alternative" tabindex="-1">YAML is the standard config, TOML the alternative <a class="header-anchor" href="#yaml-is-the-standard-config-toml-the-alternative" aria-label="Permalink to &quot;YAML is the standard config, TOML the alternative&quot;">​</a></h2><p><strong>Decision:</strong> <code>tamias.yml</code>/<code>tamias.yaml</code> is the standard manifest and project config; TOML is supported via <code>tamias-config-toml</code>.</p><p><strong>Alternatives:</strong> TOML-only (the Rust ecosystem default); JSON.</p><p><strong>Consequence:</strong> manifests read like the org&#39;s other YAML documents (peregrin campaigns, kuda cards), at the price of a second format impl to keep honest — drift between the two loaders is a real bug class.</p><h2 id="include-composes-publish-flattens" tabindex="-1"><code>include:</code> composes, publish flattens <a class="header-anchor" href="#include-composes-publish-flattens" aria-label="Permalink to &quot;`include:` composes, publish flattens&quot;">​</a></h2><p><strong>Decision:</strong> <code>include:</code> entries deep-merge into one composed tree that drivers see and the digest covers; <code>publish</code>/<code>bundle pack</code> flatten by default (<code>--keep-includes</code> ships raw).</p><p><strong>Alternatives:</strong> shipping includes unresolved (consumers re-compose); always flattening at install.</p><p><strong>Consequence:</strong> installs are self-contained and digests are stable, but a flattened publish loses the include structure — <code>--keep-includes</code> exists for packs that want consumers to compose.</p><h2 id="signing-is-optional-trust-tiers-are-computed" tabindex="-1">Signing is optional, trust tiers are computed <a class="header-anchor" href="#signing-is-optional-trust-tiers-are-computed" aria-label="Permalink to &quot;Signing is optional, trust tiers are computed&quot;">​</a></h2><p><strong>Decision:</strong> package signing uses <code>ssh-keygen -Y</code> (namespace <code>tamias-package</code>); every install computes a trust tier from pins + signatures + signers files rather than trusting a declared badge.</p><p><strong>Alternatives:</strong> mandatory signing; a bespoke signature format; registry-attested trust.</p><p><strong>Consequence:</strong> unpinned installs still work (tier <code>unpinned</code>, loudly labeled) while <code>signing.required</code> can hard-fail them for registry policies. <code>cf:</code> installs are TLS-authenticated but not sha-pinned at transport — a documented caveat, mitigated by signatures. See <a href="/tamias/explanation/security.html">Security model</a>.</p>',26)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
